import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"51 - Broker And System Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/51-broker-and-system-config.md","filePath":"developers/design-documentation/51-broker-and-system-config.md"}'),i={name:"developers/design-documentation/51-broker-and-system-config.md"};function d(n,e,s,c,l,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="_51-broker-and-system-configuration" tabindex="-1">51 - Broker And System Configuration <a class="header-anchor" href="#_51-broker-and-system-configuration" aria-label="Permalink to &quot;51 - Broker And System Configuration&quot;">​</a></h1><h2 id="configuration-sources" tabindex="-1">Configuration Sources <a class="header-anchor" href="#configuration-sources" aria-label="Permalink to &quot;Configuration Sources&quot;">​</a></h2><p>Tradeboard does not use a <code>config_service.py</code> or broker configuration database. Runtime settings come from:</p><table tabindex="0"><thead><tr><th>Source</th><th>Examples</th></tr></thead><tbody><tr><td><code>.env</code></td><td>Broker keys, redirect/host/WebSocket URLs, database paths, rate limits, security flags</td></tr><tr><td><code>broker/*/plugin.json</code></td><td>Broker name, type, exchanges, leverage capability</td></tr><tr><td>Main settings tables</td><td>Analyzer mode, SMTP, notification/application preferences</td></tr></tbody></table><p>Environment validation runs before application imports. Import-time settings require a restart after change.</p><h2 id="broker-credential-api" tabindex="-1">Broker Credential API <a class="header-anchor" href="#broker-credential-api" aria-label="Permalink to &quot;Broker Credential API&quot;">​</a></h2><p><code>blueprints/broker_credentials.py</code> provides session-authenticated <code>/api/broker/credentials</code> GET/POST and <code>/api/broker/capabilities</code> GET.</p><p>GET masks secrets with a fixed-length suffix and returns raw length separately for UI state. POST writes only supplied values to <code>.env</code>, validates redirect/host/WebSocket formats and selected broker-specific composite keys, and returns <code>restart_required: true</code>.</p><p>The UI is part of <code>frontend/src/pages/Profile.tsx</code>. Broker selection/login uses <code>BrokerSelect.tsx</code> and <code>BrokerTOTP.tsx</code>.</p><h2 id="public-broker-config" tabindex="-1">Public Broker Config <a class="header-anchor" href="#public-broker-config" aria-label="Permalink to &quot;Public Broker Config&quot;">​</a></h2><p><code>GET /auth/broker-config</code> always exposes the broker name needed to render login. API key and redirect URL are returned only for an authenticated app session. The route derives the broker key from the configured callback URL.</p><h2 id="capability-loading" tabindex="-1">Capability Loading <a class="header-anchor" href="#capability-loading" aria-label="Permalink to &quot;Capability Loading&quot;">​</a></h2><p>At startup <code>utils/plugin_loader.py</code> calls <code>load_broker_capabilities()</code>, which reads every <code>broker/*/plugin.json</code> that declares <code>supported_exchanges</code> into the module-level <code>_broker_capabilities</code> dict. All 36 plugins qualify today: 34 securities brokers, Delta Exchange for crypto derivatives, and a Dhan sandbox plugin for paper trading. <code>/api/broker/capabilities</code> reads the broker from the Flask session and serves the cached record through <code>get_broker_capabilities()</code>. No session broker returns HTTP 400. A missing capability record falls back to a minimal <code>IN_stock</code> object with an empty <code>supported_exchanges</code> list and <code>leverage_config: false</code>.</p><h2 id="security-boundaries" tabindex="-1">Security Boundaries <a class="header-anchor" href="#security-boundaries" aria-label="Permalink to &quot;Security Boundaries&quot;">​</a></h2><ul><li><code>.env</code> is installation-secret state and must not be committed.</li><li>Browser reads receive masked credentials; writes never echo submitted secrets.</li><li>Changes are CSRF-protected and session-authenticated.</li><li>Updating <code>.env</code> is not hot reload; restart is explicit.</li><li>Login-time broker tokens are encrypted in <code>database/auth_db.py</code>, separate from static broker application credentials.</li></ul><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>.sample.env</code></td><td>Environment contract and defaults</td></tr><tr><td><code>utils/env_check.py</code></td><td>Startup validation</td></tr><tr><td><code>utils/plugin_loader.py</code></td><td>Plugin/capability discovery</td></tr><tr><td><code>blueprints/broker_credentials.py</code></td><td>Credential and capability API</td></tr><tr><td><code>blueprints/auth.py</code></td><td>Broker config/login routes</td></tr><tr><td><code>frontend/src/pages/Profile.tsx</code></td><td>Configuration UI</td></tr><tr><td><code>broker/*/plugin.json</code></td><td>Capability metadata</td></tr></tbody></table>',17)])])}const h=t(i,[["render",d]]);export{b as __pageData,h as default};
